import axios from 'axios';

const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000/api';

const apiClient = axios.create({
  baseURL: API_BASE_URL,
  timeout: 20000,
  headers: { 'Content-Type': 'application/json' },
});

export const productApi = {
  searchProducts: async (params = {}) => {
    const { data } = await apiClient.get('/products/search', { params });
    return data;
  },
  getProduct: async (productId) => {
    const { data } = await apiClient.get(`/products/${encodeURIComponent(productId)}`);
    return data;
  },
  getTrending: async (limit = 12) => {
    const { data } = await apiClient.get('/products/trending', { params: { limit } });
    return data;
  },
  getSuggestions: async (q) => {
    const { data } = await apiClient.get('/products/suggestions', { params: { q } });
    return data;
  },
  getCategories: async () => {
    const { data } = await apiClient.get('/products/categories');
    return data;
  },
  getBrands: async (q = '') => {
    const { data } = await apiClient.get('/products/brands', { params: { q } });
    return data;
  },
  getRecommendations: async (payload = {}) => {
    const { data } = await apiClient.post('/products/recommendations', payload);
    return data;
  },
  getProviderStatus: async () => {
    const { data } = await apiClient.get('/products/providers');
    return data;
  },
};

export const aiApi = {
  chat: async (message) => {
    const { data } = await apiClient.post('/ai/chat', { message });
    return data;
  },
  suggest: async (query) => {
    const { data } = await apiClient.post('/ai/suggest', { query });
    return data;
  },
  sentiment: async (reviews) => {
    const { data } = await apiClient.post('/ai/sentiment', { reviews });
    return data;
  },
};

export default apiClient;
